'use strict';
(function(){
let routeKey=null,elapsed=0,shown=null;
const esc=I.esc;
const outside=i=>[975+i*21,770];
function songList(songs){return songs.length?`<div class="show-setlist">${songs.map(x=>`<div><span><strong class="song-heading">${I.songTitle(x)}</strong><small>${esc(x.genre)} · programme prévu</small>${I.songStats(x)}</span></div>`).join('')}</div>`:'<div class="hint">Aucune chanson prête pour l’instant. Le groupe effectue quand même sa sortie; préparez le prochain show au garage.</div>';}
function stage(){const a=state.tour.active;if(!a||a.phase!=='stage')return;shown=a.id+'-stage';if(a.songs.length){window.MaisonLiveUI.open(()=>result());return;}openDialog(`<div class="show-dialog"><span class="eyebrow">SEMAINE ${a.week} · LE SHOW</span><h2>Le répertoire n’est pas encore prêt.</h2><p>Aucune chanson n’a atteint 100 % d’écriture et de préparation. Le groupe ne monte pas sur scène cette fois.</p><p class="hint">Termine une chanson adoptée et répète-la au garage pour le prochain show.</p><button id="performShow" class="primary">Voir le bilan →</button></div>`);$('#performShow').onclick=()=>{if(!T.perform(state))return;save();result();};}
function result(record,history=false){$('#dialog').classList.remove('live-dialog');const a=history?record:state.tour.active,r=history?record.result:a?.result;if(!r)return;shown=a.id+'-result';openDialog(`<div class="show-dialog"><span class="eyebrow">SHOW DE LA SEMAINE ${a.week} · ${history?'SOUVENIR':'LE BILAN'}</span><h2>${esc(r.title)}</h2><p class="moment-body">${esc(r.body)}</p>${songList(r.songs)}<div class="show-effects">${r.effects.map(x=>`<p>✦ ${esc(x)}</p>`).join('')}</div><div class="show-energy">${r.people.map(x=>{const p=state.people.find(p=>p.id===x.id);return `<div>${avatar(p)}<span><strong>${p.name}</strong><small>Énergie ${x.energyBefore} → ${x.energyAfter}</small></span></div>`;}).join('')}</div>${history?`${a.direction?'<p class="hint">Après ce show : '+esc(a.direction.title)+(a.direction.fromWeek?' · semaines '+a.direction.fromWeek+'–'+a.direction.toWeek:' · mois '+a.direction.month)+'.</p>':''}<button id="closeShowMemory" class="primary">Retour à la maison</button>`:'<button id="returnFromShow" class="primary">Rentrer à la maison →</button>'}</div>`);if(history)$('#closeShowMemory').onclick=()=>closeDialog();else $('#returnFromShow').onclick=()=>{if(!T.beginReturn(state))return;save();dialogWasRunning=false;closeDialog();render();};}
function showCurrent(){const a=state.tour.active;if(!a)return;if(a.phase==='stage')stage();else if(a.phase==='result')result();else toast(T.activity(state)+'. Le départ est prévu à 11 h et le retour à 22 h.');}
function maybeShow(){if(window.homeOpen||window.MaisonLiveUI?.isOpen())return false;const a=state.tour.active;if(!a||$('#dialog').open)return false;if(['stage','result'].includes(a.phase)&&shown!==a.id+'-'+a.phase){showCurrent();return true;}return false;}
function prepareRoute(a){const key=a.id+'-'+a.phase;if(routeKey===key)return;routeKey=key;elapsed=0;if(!['departing','returning'].includes(a.phase))return;for(let i=0;i<a.people.length;i++){const id=a.people[i],p=state.people.find(p=>p.id===id),pos=positions[id];if(!pos)continue;const end=outside(i);pos.el.classList.add('tour-travel');if(a.phase==='departing'){pos.queue=H.tourPath(p.room,end);}else{pos.x=end[0];pos.y=end[1];pos.room=p.room;pos.queue=H.tourPath(p.room,H.position(state,p),true);}pos.el.style.opacity='1';}}
function renderTour(){const a=state.tour.active,van=$('#showVan'),banner=$('#tourBanner');$('#newComposition').disabled=!!a;$('#invite').disabled=false;van.hidden=!a;van.classList.toggle('on-road',!!a&&['stage','result'].includes(a.phase));banner.hidden=!a;$('#map').classList.toggle('show-excitement',!!a);if(!a){routeKey=null;for(const pos of Object.values(positions)){pos.el.classList.remove('tour-travel');pos.el.style.opacity='';}return;}if(T.blocking(state))setRunning(false);prepareRoute(a);const label=({preparing:'On se prépare pour le show',coffee:'Un café ensemble avant de partir',packing:'On prépare les instruments',departing:'11 h · Tout le monde en route !',returning:'22 h · Les voilà de retour !',unpacking:'On range les instruments',stage:'Le groupe est sur scène',result:'Le show est terminé'})[a.phase];banner.innerHTML=`<span class="tour-note">♫</span><div><strong>${label}</strong><small>Show de la semaine ${a.week} · ${a.phase==='unpacking'?'La soirée reprend à 22 h 30':'Départ 11 h · retour 22 h'}</small></div>${['stage','result'].includes(a.phase)?'<button id="resumeShow" class="primary">'+(a.phase==='stage'?'Voir le show':'Voir le bilan')+' ↗</button>':''}`;if($('#resumeShow'))$('#resumeShow').onclick=showCurrent;if(['stage','result'].includes(a.phase))for(const pos of Object.values(positions))pos.el.style.opacity='0';maybeShow();}
function frame(dt){const a=state.tour.active;if(!a||!['departing','returning'].includes(a.phase)||document.hidden||$('#dialog').open)return;prepareRoute(a);elapsed+=dt;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;let done=0;for(let i=0;i<a.people.length;i++){const pos=positions[a.people[i]];if(!pos)continue;if(!reduced&&elapsed<i*.16)continue;let budget=reduced?100000:dt*480;while(pos.queue.length&&budget>0){const [x,y]=pos.queue[0],dx=x-pos.x,dy=y-pos.y,d=Math.hypot(dx,dy);if(d<=budget){pos.x=x;pos.y=y;pos.queue.shift();budget-=d;}else{pos.x+=dx/d*budget;pos.y+=dy/d*budget;budget=0;}}pos.el.style.left=pos.x/H.WIDTH*100+'%';pos.el.style.top=pos.y/H.HEIGHT*100+'%';pos.el.classList.toggle('moving',pos.queue.length>0);if(!pos.queue.length){done++;if(a.phase==='departing')pos.el.style.opacity='0';}}
if(done===a.people.length&&elapsed>(reduced?.2:1)){if(a.phase==='departing')T.arriveAtVenue(state);else T.arriveHome(state);save();render();if(state.tour.active?.phase==='unpacking')setRunning(true);}}
window.MaisonTourUI={showCurrent,maybeShow,render:renderTour,frame,showHistory:m=>{const record=T.completed(state,m);if(record)result(record,true);},resetView:()=>{window.MaisonLiveUI?.reset();routeKey=null;shown=null;elapsed=0;}};renderTour();
})();
